const crypto = require('crypto');

const body = $input.first().json.body || $input.first().json;
const received = String(body.token || '');
const expected = String($env.RC_OUTGOING_TOKEN || '');

if (!expected) throw new Error('RC_OUTGOING_TOKEN no configurado');
if (received.length !== expected.length ||
    !crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected))) {
  throw new Error('Token de integracion invalido');
}

return [{
  json: {
    channel_id:   body.channel_id,
    channel_name: body.channel_name,
    message_id:   body.message_id,
    user_id:      body.user_id,
    user_name:    body.user_name,
    text:         String(body.text || '').trim(),
  }
}];

const item = $input.first().json;
const m = item.text.match(/^!ir\s+(\w+)(?:\s+(\S+))?(?:\s+(\S+))?(?:\s+(\S+))?/i);

if (!m) return [{ json: { ...item, verb: 'help', invalid: true } }];

const SCRIPTS = ['disable_account.ps1','enable_account.ps1',
                 'collect_logs.ps1','isolate_host.ps1','reset_password.ps1'];

const verb = m[1].toLowerCase();
const arg1 = m[2] || '';
const arg2 = m[3] || '';
const arg3 = m[4] || '';
const out = { ...item, verb, arg1, arg2, arg3, invalid: false };

if (verb === 'run') {
  if (!SCRIPTS.includes(arg1)) {
    out.invalid = true; out.error = `Script no permitido desde el canal: ${arg1}`;
  } else if (!/^[A-Za-z0-9._\-\\]{1,64}$/.test(arg2)) {
    out.invalid = true; out.error = 'Target invalido';
  }
}

if (verb === 'rustdesk') {
  const ttl = parseInt(arg1 || '30', 10);
  if (!Number.isInteger(ttl) || ttl < 1 || ttl > 240) {
    out.invalid = true; out.error = 'TTL fuera de rango (1-240)';
  } else out.ttl_minutes = ttl;
}

// KVM (Fase 8): concede una ventana de 15 min a un usuario de rttys.
// Uso: !ir kvm <devid> <cmd|web> <usuario_rttys>
// 'connect' no se solicita: se autoriza sin aprobación (F8-D5).
if (verb === 'kvm') {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(arg1)) {
    out.invalid = true; out.error = 'devid invalido';
  } else if (!['cmd','web'].includes(arg2)) {
    out.invalid = true; out.error = 'Accion invalida (cmd|web)';
  } else if (!/^[a-zA-Z0-9]{1,32}$/.test(arg3)) {
    out.invalid = true; out.error = 'Falta el usuario de rttys al que se concede';
  }
}

if ((verb === 'approve' || verb === 'deny') && !/^REQ-[a-f0-9]{8}$/.test(arg1)) {
  out.invalid = true; out.error = 'Identificador de solicitud invalido';
}

return [{ json: out }];

const cmd     = $('Parse Command').first().json;
const msgResp = $input.first().json;

if (!msgResp.success || !msgResp.message) {
  throw new Error('Mensaje no encontrado en Rocket.Chat');
}
if (msgResp.message.u._id !== cmd.user_id) {
  throw new Error('Autor del mensaje no coincide con el payload');
}

// Autorización por allowlist mantenida en el orquestador.
// Rocket.Chat Community no permite roles propios y el bot no tiene
// view-full-other-user-info, por lo que users.info no devuelve roles.
// Ventaja de diseño: un compromiso de Rocket.Chat permite publicar
// mensajes, pero no añadirse a la lista de aprobadores.
const approvers = ($env.IR_APPROVER_IDS || '').split(',').map(s => s.trim());

return [{
  json: {
    ...cmd,
    authorized:  approvers.includes(msgResp.message.u._id),
    rc_username: msgResp.message.u.username,
    rc_user_id:  msgResp.message.u._id,
  }
}];

const d = $input.first().json;
let msg;

if (!d.authorized) {
  msg = `🚫 @${d.user_name}: no estás autorizado para operar el canal break-glass.`;
} else if (d.invalid) {
  msg = `⚠️ ${d.error || 'Comando no reconocido'}`;
} else if (d.verb === 'help') {
  msg = `**Comandos break-glass**\n` +
        `\`!ir run <script.ps1> <target>\` — solicitar ejecución\n` +
        `\`!ir rustdesk <minutos>\` — solicitar acceso remoto\n` +
        `\`!ir kvm <devid> <cmd|web> <usuario_rttys>\` — conceder ventana de 15 min en el KVM\n` +
        `\`!ir approve REQ-xxxxxxxx\` — aprobar (requiere segundo responsable)\n` +
        `\`!ir deny REQ-xxxxxxxx\` — denegar\n` +
        `\`!ir status\` — solicitudes pendientes`;
} else {
  msg = 'ℹ️ Sin solicitudes pendientes.';
}

return [{ json: { channel_id: d.channel_id, mensaje: msg } }];

const crypto = require('crypto');
const cmd = $input.first().json;
const store = $getWorkflowStaticData('global');

if (!store.requests) store.requests = {};

const AHORA  = Date.now();
const TTL_MS = 15 * 60 * 1000;

// Purga de solicitudes caducadas.
// Una solicitud de KVM aprobada se conserva mientras su ventana siga viva:
// a diferencia de run/rustdesk, la aprobación no ejecuta nada, abre un plazo.
for (const [k, v] of Object.entries(store.requests)) {
  const ventanaViva = v.verb === 'kvm' && v.status === 'approved' &&
                      v.approved_at && (AHORA - v.approved_at) <= TTL_MS;
  if (!ventanaViva && AHORA - v.created_at > TTL_MS) delete store.requests[k];
}

const requestId = 'REQ-' + crypto.randomBytes(4).toString('hex');

store.requests[requestId] = {
  request_id:   requestId,
  verb:         cmd.verb,
  script:       cmd.verb === 'run' ? cmd.arg1 : (cmd.verb === 'kvm' ? '' : 'rustdesk_enable.ps1'),
  target:       cmd.verb === 'run' ? cmd.arg2 : '',
  devid:        cmd.verb === 'kvm' ? cmd.arg1 : '',
  kvm_accion:   cmd.verb === 'kvm' ? cmd.arg2 : '',
  kvm_usuario:  cmd.verb === 'kvm' ? cmd.arg3 : '',
  ttl_minutes:  cmd.ttl_minutes || 30,
  requester_id: cmd.rc_user_id,
  requester:    cmd.rc_username,
  channel_id:   cmd.channel_id,
  created_at:   AHORA,
  status:       'pending',
};

const accion = cmd.verb === 'run'
  ? `Ejecutar \`${cmd.arg1}\` sobre \`${cmd.arg2}\``
  : cmd.verb === 'kvm'
  ? `KVM: conceder \`${cmd.arg2}\` sobre \`${cmd.arg1}\` a \`${cmd.arg3}\``
  : `Activar acceso remoto RustDesk (TTL ${cmd.ttl_minutes} min)`;

const nota = cmd.verb === 'kvm'
  ? `\n_Al aprobar se abre una ventana de 15 minutos durante la cual \`${cmd.arg3}\` puede ejecutar \`${cmd.arg2}\` sobre \`${cmd.arg1}\`. La aprobación no ejecuta nada por sí misma._`
  : '';

const mensaje =
  `⏳ **Solicitud \`${requestId}\` pendiente de aprobación**\n` +
  `**Acción:** ${accion}\n` +
  `**Solicitante:** @${cmd.rc_username}\n` +
  `**Caduca:** en 15 minutos\n\n` +
  `Un segundo responsable debe aprobar con \`!ir approve ${requestId}\`.\n` +
  `_El solicitante no puede aprobar su propia petición._` + nota;

return [{ json: { request_id: requestId, channel_id: cmd.channel_id, mensaje } }];

const cmd = $input.first().json;
const store = $getWorkflowStaticData('global');
const requestId = cmd.arg1;
const req = (store.requests || {})[requestId];

if (!req) {
  return [{ json: { ok: false, channel_id: cmd.channel_id,
    mensaje: `❌ Solicitud \`${requestId}\` no encontrada o caducada.` } }];
}

if (req.status !== 'pending') {
  return [{ json: { ok: false, channel_id: cmd.channel_id,
    mensaje: `❌ Solicitud \`${requestId}\` ya resuelta (${req.status}).` } }];
}

if (Date.now() - req.created_at > 15 * 60 * 1000) {
  req.status = 'expired';
  return [{ json: { ok: false, channel_id: cmd.channel_id,
    mensaje: `❌ Solicitud \`${requestId}\` caducada.` } }];
}

// REGLA DE DOS PERSONAS
if (req.requester_id === cmd.rc_user_id) {
  return [{ json: { ok: false, channel_id: cmd.channel_id, autoaprobacion: true,
    mensaje: `🚫 **Rechazado:** el solicitante no puede aprobar su propia petición.\n` +
             `La solicitud \`${requestId}\` requiere un segundo responsable.` } }];
}

if (cmd.verb === 'deny') {
  req.status = 'denied';
  req.approver = cmd.rc_username;
  return [{ json: { ok: false, channel_id: cmd.channel_id,
    mensaje: `🛑 Solicitud \`${requestId}\` denegada por @${cmd.rc_username}.` } }];
}

req.status      = 'approved';
req.approver    = cmd.rc_username;
req.approver_id = cmd.rc_user_id;
req.approved_at = Date.now();

return [{
  json: {
    ok: true,
    request_id:  requestId,
    script:      req.script,
    target:      req.target,
    ttl_minutes: req.ttl_minutes,
    verb:        req.verb,
    requester:   req.requester,
    approver:    cmd.rc_username,
    channel_id:  req.channel_id,
    devid:       req.devid,
    kvm_accion:  req.kvm_accion,
    kvm_usuario: req.kvm_usuario,
  }
}];

const crypto = require('crypto');
const d = $input.first().json;

const payload = d.verb === 'rustdesk'
  ? { script: 'rustdesk_enable.ps1', ttl_minutes: d.ttl_minutes }
  : { script: d.script, target: d.target };

const bodyStr = JSON.stringify(payload);
const ts      = Math.floor(Date.now() / 1000).toString();
const nonce   = crypto.randomBytes(16).toString('hex');
const sig     = crypto.createHmac('sha256', $env.AGENT_HMAC_SECRET)
                      .update(`${ts}.${nonce}.${bodyStr}`)
                      .digest('hex');
return [{ json: { ...d, bodyStr, ts, nonce, sig,
  dbg_url: `${$env.DC_AGENT_URL}/run`,
  dbg_token_len: String($env.AGENT_TOKEN || '').length,
  dbg_token_ini: String($env.AGENT_TOKEN || '').slice(0,6),
} }];
return [{ json: { ...d, bodyStr, ts, nonce, sig } }];

const agent = $('Call DC Agent').first().json;
const meta  = $('Validate Approval').first().json;
const store = $getWorkflowStaticData('global');

if (!store.credentials) store.credentials = {};

// El agente mezcla la salida del binario con el JSON: tomamos la última línea
let salida = {};
try {
  const lineas = String(agent.stdout || '').trim().split('\n');
  salida = JSON.parse(lineas[lineas.length - 1]);
} catch (e) {
  salida = {};
}

let mensaje;

if (meta.verb === 'rustdesk' && salida.password) {
  const ttlMs = (meta.ttl_minutes || 30) * 60 * 1000;

  // Purga de credenciales caducadas
  const ahora = Date.now();
  for (const [k, v] of Object.entries(store.credentials)) {
    if (ahora > v.expires_at) delete store.credentials[k];
  }

  store.credentials[meta.request_id] = {
    password:    salida.password,
    rustdesk_id: '161180321',   // provisional: se resolverá desde hbbs
    expires_at:  ahora + ttlMs,
    consumed:    false,
    requester:   meta.requester,
    approver:    meta.approver,
  };

  mensaje =
    `✅ **Acceso break-glass concedido** — solicitud \`${meta.request_id}\`\n` +
    `**Servicio:** ${salida.service || 'desconocido'} · **TTL:** ${meta.ttl_minutes} min\n` +
    `**Solicitado por:** @${meta.requester} · **Aprobado por:** @${meta.approver}\n\n` +
    `🔑 **Credencial:** [Recuperar acceso](${$env.CREDENTIAL_BASE_URL}?id=${meta.request_id})\n` +
    `_Requiere MFA. Se muestra una sola vez y caduca con el TTL._`;
} else {
  mensaje =
    `${agent.returncode === 0 ? '✅' : '⚠️'} **Acción ejecutada** — solicitud \`${meta.request_id}\`\n` +
    `**Script:** \`${meta.script}\` · **Código:** ${agent.returncode}\n` +
    `**Solicitado por:** @${meta.requester} · **Aprobado por:** @${meta.approver}\n` +
    (agent.stdout ? '```\n' + String(agent.stdout).slice(0, 1200) + '\n```' : '');
}

return [{ json: { channel_id: meta.channel_id, mensaje } }];

const req = $input.first().json;
const requestId = (req.query && req.query.id) || '';
const store = $getWorkflowStaticData('global');
const cred = (store.credentials || {})[requestId];

// Authelia ya validó MFA y pertenencia al grupo antes de llegar aquí
const usuario = (req.headers && req.headers['remote-user']) || 'desconocido';

const pagina = (titulo, cuerpo) =>
  `<html><head><meta charset="utf-8"><title>Break-glass</title></head>
   <body style="font-family:sans-serif;padding:2rem;max-width:40rem">
   <h3>${titulo}</h3>${cuerpo}</body></html>`;

if (!cred) {
  return [{ json: { html: pagina('Credencial no encontrada',
    '<p>La solicitud no existe o ya expiró.</p>') } }];
}
if (cred.consumed) {
  return [{ json: { html: pagina('Credencial ya consumida',
    `<p>Recuperada por <b>${cred.consumed_by}</b>. Solicita un nuevo acceso.</p>`) } }];
}
if (Date.now() > cred.expires_at) {
  delete store.credentials[requestId];
  return [{ json: { html: pagina('Credencial caducada',
    '<p>El TTL de la sesión ha expirado.</p>') } }];
}

const pass = cred.password;
const id   = cred.rustdesk_id;

cred.consumed    = true;
cred.consumed_by = usuario;
cred.consumed_at = Date.now();
cred.password    = '';

return [{
  json: {
    audit: `CREDENCIAL request_id=${requestId} consumida_por=${usuario}`,
    html: pagina(`Acceso break-glass — ${requestId}`,
      `<p><b>ID RustDesk:</b> <code style="font-size:1.2em">${id}</code></p>
       <p><b>Contraseña:</b> <code style="font-size:1.2em">${pass}</code></p>
       <p style="margin-top:1.5rem">
         <a href="rustdesk://connection/new/${id}"
            style="background:#0b6;color:#fff;padding:.6rem 1rem;
                   text-decoration:none;border-radius:4px">Abrir en RustDesk</a>
       </p>
       <p style="color:#a00;margin-top:2rem">
         Esta credencial no volverá a mostrarse.</p>`)
  }
}];

const fs = require('fs');
const d = $input.first().json;

let rustdeskId = 'no_resuelto';
try {
  const peers = JSON.parse(fs.readFileSync('/data/peers.json', 'utf8'));
  // El inventario hostname <-> ID se mantiene en el campo 'note' de hbbs.
  // Filtrar por él evita depender del orden y distingue el endpoint objetivo
  // de otros clientes registrados en el mismo servidor de rendezvous.
  const peer = peers.find(p => p.note === 'dc01-tfm');
  if (peer) rustdeskId = peer.id;
} catch (e) {
  // Se registra pero no bloquea el flujo
}

return [{ json: { ...d, rustdesk_id: rustdeskId } }];

// Consulta de aprobación vigente para el hook del KVM (Fase 8).
// No modifica el estado: sólo lee. La purga la hace Create Request, así que
// aquí se comprueba la caducidad por cuenta propia.
const q = $('Webhook Consulta KVM').first().json.query || {};
const store = $getWorkflowStaticData('global');
const AHORA = Date.now();
const VENTANA_MS = 15 * 60 * 1000;

const vale = Object.values(store.requests || {}).find(r =>
  r.verb === 'kvm' &&
  r.status === 'approved' &&
  r.kvm_usuario === q.username &&
  r.devid === q.devid &&
  r.kvm_accion === q.accion &&
  r.approved_at && (AHORA - r.approved_at) < VENTANA_MS
);

return [{ json: {
  ok: true,
  autorizado: !!vale,
  request_id: vale ? vale.request_id : null,
  aprobador:  vale ? vale.approver : null,
  consulta:   { username: q.username || '', devid: q.devid || '', accion: q.accion || '' },
} }];

const d = $input.first().json;

const PORTAL  = 'https://kvm.oob.local/#/login';
const CONSOLA = `https://kvm.oob.local/#/rtty/${d.devid}`;
const WEB     = `https://kvm.oob.local/web/${d.devid}/https/127.0.0.1%3A443%2F`;
const accesos = d.kvm_accion === 'web'
  ? `**1.** [Iniciar sesión en la plataforma KVM](${PORTAL}) como \`${d.kvm_usuario}\`\n` +
    `**2.** [Abrir control remoto (vídeo)](${WEB})`
  : `**1.** [Iniciar sesión en la plataforma KVM](${PORTAL}) como \`${d.kvm_usuario}\`\n` +
    `**2.** [Abrir consola del dispositivo](${CONSOLA})\n\n` +
    `La acción \`cmd\` se ejecuta desde la interfaz; no tiene enlace propio.`;
const msg =
  `✅ **Ventana KVM abierta** (\`${d.request_id}\`)\n` +
  `**Usuario:** \`${d.kvm_usuario}\` · **Dispositivo:** \`${d.devid}\` · **Acción:** \`${d.kvm_accion}\`\n` +
  `**Aprobada por:** @${d.approver} · **Solicitada por:** @${d.requester}\n` +
  `**Vigencia:** 15 minutos desde ahora.\n\n` +
  `${accesos}`;

return [{ json: { channel_id: d.channel_id, mensaje: msg } }];
